// Create a text index
await articles.createIndex({ title: "text", body: "text" });

// Search for documents containing "mongodb"
const results = await articles.find(
  { $text: { $search: "mongodb aggregation" } },
  { projection: { score: { $meta: "textScore" }, title: 1 } }
).sort({ score: { $meta: "textScore" } }).toArray();
